// Embedded Base64 backups guaranteeing instant load without network dependency
const EMBEDDED_SAMPLES: Record<string, string> = {
  "demo-blurred.png": "",
  "sample-blurred.png": "",
  "demo-ood.png": "",
  "sample-ood.png": "",
  "demo-uncertain.png": "",
  "sample-uncertain.png": "",
  "sample-normal.png": "",
  "demo-normal.png": "",
  "sample-pneumonia.png": "",
  "demo-pneumonia.png": "",
};

function base64ToBlob(base64: string, mimeType = 'image/png'): Blob {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return new Blob([bytes], { type: mimeType });
}

function base64ToFile(base64: string, filename: string): File {
  const blob = base64ToBlob(base64, 'image/png');
  return new File([blob], filename, { type: 'image/png' });
}

function resolveFallbackData(key: string): string | null {
  const cleaned = key.split('?')[0].split('#')[0].split('/').pop() || key;
  if (EMBEDDED_SAMPLES[cleaned]) return EMBEDDED_SAMPLES[cleaned];
  if (EMBEDDED_SAMPLES[key]) return EMBEDDED_SAMPLES[key];
  
  const lower = cleaned.toLowerCase();
  for (const [k, v] of Object.entries(EMBEDDED_SAMPLES)) {
    if (lower.includes('normal') && k.includes('normal')) return v;
    if (lower.includes('pneumonia') && k.includes('pneumonia')) return v;
    if (lower.includes('uncertain') && k.includes('uncertain')) return v;
    if (lower.includes('blur') && k.includes('blur')) return v;
    if (lower.includes('ood') && k.includes('ood')) return v;
  }
  return null;
}

/**
 * Loads a sample radiograph as a valid File object.
 * First resolves via network/Vite asset URL, falling back instantaneously
 * to the embedded base64 representation if network or routing fails.
 */
export async function loadSampleAsset(pathOrName: string, preferredFilename?: string): Promise<File> {
  const filename = preferredFilename || pathOrName.split('/').pop() || 'sample.png';

  // 1. Attempt fetching via HTTP / Vite dev server
  try {
    const res = await fetch(pathOrName);
    if (res.ok) {
      const cType = res.headers.get('content-type') || '';
      // Reject if Vite / SPA fallback returned HTML (e.g. index.html on 404)
      if (!cType.includes('text/html')) {
        const blob = await res.blob();
        if (blob.size > 200) {
          return new File([blob], filename, { type: 'image/png' });
        }
      }
    }
  } catch {
    // Network or CORS failure — proceed to embedded fallback
  }

  // 2. Embedded fallback
  const fallbackBase64 = resolveFallbackData(filename) || resolveFallbackData(pathOrName);
  if (fallbackBase64) {
    return base64ToFile(fallbackBase64, filename);
  }

  throw new Error(`Failed to load sample asset: ${filename}`);
}
